#include <Arduino.h>
#include "console.h"
#include <WiFi.h>
#include <Preferences.h>
#include <ArduinoJson.h>
#include "protocol.h"
#include "physical_io.h"
#include "radio_v3.h"
Preferences prefs;uint8_t centralMac[6],lmk[16];uint32_t slaveBoot=0,centralBoot=0,lastSequence=0,lastHello=0,lastReport=0,lastScan=0;uint8_t radioChannel=1;bool paired=false,timeKnown=false;QueueHandle_t queue;
String serialLine,activeCommands[CHANNELS];uint32_t activeTarget[CHANNELS]={};
void receiveFrame(const uint8_t*mac,const uint8_t*raw,int n){if(!paired||memcmp(mac,centralMac,6)||n!=sizeof(RadioFrame))return;RadioFrame f;memcpy(&f,raw,n);if(radioValid(f,lmk))xQueueSend(queue,&f,0);}
void sendStatus(uint8_t type=R_STATUS,const char*command="",bool ok=false,uint8_t channel=0){RadioFrame f;f.type=type;f.channel=channel;f.senderBoot=slaveBoot;f.targetBoot=centralBoot;f.success=ok;f.outputs=enabledMask;strlcpy(f.command,command,37);for(int i=0;i<CHANNELS;i++)f.states[i]=reedState(i);f.pump=pumpEnabled&&pumpCounter.known?(pumpCounter.running?1:0):-1;f.cycles=pumpCounter.cycles;f.runtimeSeconds=pumpCounter.milliseconds/1000;strlcpy(f.counterEpoch,counterEpoch.c_str(),33);radioSign(f,lmk);esp_now_send(centralMac,(uint8_t*)&f,sizeof(f));}
bool pairing(JsonVariant d){uint8_t p[16];return parseMac(d["centralMac"].as<String>(),centralMac)&&unhex(d["lmk"].as<String>(),lmk,16)&&unhex(d["pmk"].as<String>(),p,16)&&d["profile"]==NX_PROFILE&&d["channel"].as<int>()>=1&&d["channel"].as<int>()<=13;}
void serialTick(){while(Serial.available()){char c=Serial.read();if(c=='\r')continue;if(c!='\n'){if(serialLine.length()<4096)serialLine+=c;else serialLine="";continue;}if(serialLine=="INFO"){DynamicJsonDocument d(512);d["profile"]=NX_PROFILE;d["mac"]=WiFi.macAddress();d["channel"]=radioChannel;String out;serializeJson(d,out);Serial.println("INFO "+out);}else if(serialLine.startsWith("PAIR ")){DynamicJsonDocument d(2048);if(deserializeJson(d,serialLine.substring(5))||!pairing(d.as<JsonVariant>())||!physicalConfig(d.as<JsonVariant>()))Serial.println("PAIR_ERROR");else{prefs.putString("pair",serialLine.substring(5));Serial.println("PAIR_OK");Serial.flush();delay(150);ESP.restart();}}serialLine="";}}
void setup(){Serial.begin(115200);ioBegin();prefs.begin("nx-slave-v3",false);slaveBoot=esp_random();queue=xQueueCreate(8,sizeof(RadioFrame));WiFi.mode(WIFI_STA);WiFi.setSleep(false);DynamicJsonDocument d(2048);if(deserializeJson(d,prefs.getString("pair",""))||!pairing(d.as<JsonVariant>())){Serial.println("Aguardando pareamento USB. Saidas desligadas.");return;}radioChannel=d["channel"];esp_wifi_set_channel(radioChannel,WIFI_SECOND_CHAN_NONE);uint8_t pmk[16];unhex(d["pmk"].as<String>(),pmk,16);if(!queue||esp_now_init()!=ESP_OK)return;esp_now_set_pmk(pmk);if(!addEncryptedPeer(centralMac,lmk))return;paired=true;esp_now_register_recv_cb(receiveFrame);Serial.println(String("NEXUS ")+NX_PROFILE+" 1.1.0 | somente escravo");}
void loop(){serialTick();ioTick();if(!paired){delay(5);return;}RadioFrame f;while(xQueueReceive(queue,&f,0)==pdTRUE){f.command[36]=0;if(f.targetBoot!=slaveBoot)continue;if(f.type==R_HELLO){if(f.expires<1700000000||(timeKnown&&f.expires+5<time(nullptr)))continue;if(centralBoot!=f.senderBoot){centralBoot=f.senderBoot;lastSequence=0;}struct timeval tv={(long)f.expires,0};settimeofday(&tv,nullptr);timeKnown=true;lastHello=millis();}else if(f.type==R_PULSE){int i=int(f.channel)-1;bool fresh=timeKnown&&f.senderBoot==centralBoot&&f.sequence>lastSequence&&f.expires>time(nullptr)&&f.expires<=time(nullptr)+8;if(fresh)lastSequence=f.sequence;bool ok=fresh&&i>=0&&i<CHANNELS&&startOutput(i,String(f.command),f.pulseMs);if(ok){activeCommands[i]=f.command;activeTarget[i]=f.senderBoot;}else sendStatus(R_ACK,f.command,false,f.channel);}}
for(int i=0;i<CHANNELS;i++)if(outputDone[i]){outputDone[i]=false;outputBusy[i]=false;if(activeCommands[i].length()){sendStatus(R_ACK,activeCommands[i].c_str(),true,i+1);activeCommands[i]="";}}
uint32_t now=millis();if(now-lastHello>10000&&now-lastScan>=700){lastScan=now;radioChannel=radioChannel%13+1;esp_wifi_set_channel(radioChannel,WIFI_SECOND_CHAN_NONE);sendStatus();}if(now-lastReport>=2000){lastReport=now;sendStatus();}delay(5);}
